"use strict";(self.webpackChunk_N_E=self.webpackChunk_N_E||[]).push([[759],{759:function(e){e.exports=JSON.parse('{"Index":{"harnessMetaTitle":"DeepSeek Harness developer preview: Everything is a plugin","harnessMetaDesc":"DeepSeek Harness is now available in developer preview to developers building agent harnesses worldwide, with the source code released at the same time. Every agent capability is implemented as a plugin that can be swapped or recomposed.","harnessHeroTitlePre":"Everything is a plugin","harnessHeroTitlePost":"","harnessHeroSubtitle":"DeepSeek Harness developer preview","harnessPreviewBadge":"Developer preview","harnessPreviewLabel":"DeepSeek Harness developer preview","harnessHeroDesc":"DeepSeek Harness is now in developer preview for agent harness developers worldwide — source code included.","harnessHeroDesc2":"Every capability is a plugin that can be swapped or recomposed: models, tools, skills, sessions, sandboxes, storage, loops, scheduling, and the UI.","harnessHeroGithub":"View on GitHub","harnessHeroCopy":"Copy","harnessHeroCopied":"Copied","harnessHeroWebTab":"Quick start","harnessHeroStartTab":"Install from source","harnessWhyTitlePrefix":"","harnessWhyTitleSuffix":"keeps agents working in real-world environments","harnessWhyFormula":"Agent = Model + Harness","harnessWhyP1":"The model is the soul of an agent.","harnessWhyP2":"A harness lets an agent understand its environment, use tools, and keep working in real-world settings.","harnessPillar1Title":"Cordis kernel","harnessPillar1En":"CORDIS KERNEL","harnessPillar1Desc":"The Cordis kernel manages plugin mounting, unmounting, and dependencies. Agent capabilities live in the plugins.","harnessPillar2Title":"Capabilities as plugins","harnessPillar2En":"CAPABILITIES AS PLUGINS","harnessPillar2Desc":"Plugins provide every agent capability, including models, tools, skills, sessions, sandboxes, storage, loops, scheduling, and the UI. Cordis services and events let the plugins work together.","harnessPillar3Title":"Compose with configuration","harnessPillar3En":"COMPOSE IN CONFIGURATION","harnessPillar3Desc":"Developers can select, swap, or extend any capability in configuration without changing the DeepSeek Harness source code.","harnessFeatEyebrow":"Design approach","harnessFeatTitle":"Everything is a plugin.\\nEvery run is traceable.","harnessFeat1Label":"Everything is a plugin","harnessFeat1DescPrefix":"DeepSeek Harness is built on ","harnessFeat1DescSuffix":"\'s plugin system. Plugins provide every agent capability, including models, tools, skills, sessions, sandboxes, storage, loops, scheduling, and the UI. Cordis services and events let the plugins work together. Developers can select, swap, or extend any capability in configuration without changing the DeepSeek Harness source code.","harnessFeat1Alt":"Compose models, tools, storage, and the agent loop through Cordis configuration","harnessFeat1ScreenshotAlt":"DeepSeek Harness settings showing installed plugins and their status","harnessFeat2Label":"Every run is traceable","harnessFeat2Desc":"Everything the model sees is recorded in an append-only session log: system prompts, reasoning, tool calls and results, subagent scheduling, and every context injection. In the Trajectory view, you can inspect these records by source. Resume, fork, search, and replay all operate on the same event stream.","harnessFeat2Alt":"Reconstruct a complete run from a single session log","harnessFeat3Label":"Multiple runtime modes","harnessFeat3Desc":"Standard mode includes the full toolset. Code mode uses model-generated code to orchestrate multiple rounds of tool calls. Minimal mode keeps only a shell tool and a file editor for benchmarking models in a minimal environment. Creator mode lets you inspect the current runtime, test Cordis plugins in memory, and combine them into new modes.","harnessModePlaceholder":"Describe what you want to build","harnessModeStandardName":"Standard mode","harnessModeStandardDesc":"Full coding agent with file editing, shell, file and web search, skills, planning, goals, subagents, and workflows.","harnessModeCodeName":"Code mode","harnessModeCodeDesc":"All Standard mode capabilities, with tools exposed through the Code Mode SDK so the model can combine multi-step operations in one TypeScript program.","harnessModeMinimalName":"Minimal mode","harnessModeMinimalDesc":"Two-tool coding agent with persistent bash and str_replace_editor.","harnessModeCordisName":"Creator mode","harnessModeCordisDesc":"Built for creating custom agent presets, with all Standard mode capabilities plus runtime inspection, plugin experiments, and preset-authoring guidance.","harnessDemoTitle":"Customize your DeepSeek Harness","harnessDemoDesc":"Watch how you can customize page elements, tools, and agent presets in real time.","harnessDemoAlt":"DeepSeek Harness product feature demo video","harnessUseEyebrow":"Get started","harnessUseTitle":"Try it now or install from source","harnessUse1Label":"Quick start","harnessUse1Desc":"Install Node.js, then launch the Web UI with npx.","harnessUse1Alt":"DeepSeek Harness dark-mode Web UI analyzing a project and switching between Chat and Trajectory","harnessUse2Label":"Install from source","harnessUse2Desc":"Clone the full source and follow the setup instructions in the repository.","harnessUse2Alt":"Clone, install, build, and launch the DeepSeek Harness Web UI from source","harnessCtaEyebrow":"Developer preview","harnessCtaTitle":"Join the DSH plugin ecosystem","harnessCtaDesc":"DeepSeek Harness remains in developer preview and is still being tested by developers building agent harnesses. Its core plugins and APIs will continue to evolve. We look forward to exploring the limits of intelligence with developers worldwide using open-source infrastructure that is reusable and composable.","harnessCtaDocs":"Developer docs","harnessCtaPaper":"Cordis paper","harnessCtaPlugins":"Community plugins","harnessFooterCopyright":"\xa9 2026 DeepSeek. All rights reserved.","harnessFooterPolicyLinks":"Policies and statements","harnessFooterSafeUse":"Safe Use Policy","harnessFooterDataProcessing":"Data Processing Statement","wechatLabel":"Official WeChat account","wechatTooltip":"Scan to follow","harnessFooterLicense":"Open source \xb7 MIT","harnessFeat3Alt":"The new-session mode picker listing Standard, Code, Minimal, and Creator modes"},"SafeUsePolicy":{"metaTitle":"Safe Use Policy","metaDesc":"Read the DeepSeek Harness security recommendations, use restrictions, and reporting guidance.","title":"Safe Use Policy","backHome":"Back to Harness"},"DataProcessingStatement":{"metaTitle":"Data Processing Statement","metaDesc":"Learn what DeepSeek Harness processes locally, what may be reported, and how third-party services handle data.","title":"Data Processing Statement","backHome":"Back to Harness"}}')}}]);